mcq("mcq08", ("किसी वृत्त के व्यास के सिरों पर खींची गई स्पर्श रेखाएँ होती हैं:", "વર્તુળના વ્યાસના છેડા પર દોરેલા સ્પર્શકો હોય છે:"), ("दोनों एक ही व्यास पर लंब हैं, अतः समांतर हैं।", "બંને એક જ વ્યાસને લંબ છે, તેથી સમાંતર છે."),
    {"parallel": ("सही!", "સાચું!"), "perpendicular": ("दोनों व्यास पर लंब हैं, अतः परस्पर समांतर हैं।", "બંને વ્યાસને લંબ છે, તેથી પરસ્પર સમાંતર છે."), "intersecting at the centre": ("स्पर्श रेखाएँ केंद्र से कभी नहीं जातीं।", "સ્પર્શકો ક્યારેય કેન્દ્રમાંથી પસાર થતા નથી."), "equal to the diameter": ("स्पर्श रेखाओं की कोई निश्चित लंबाई नहीं होती।", "સ્પર્શક રેખાની કોઈ નિશ્ચિત લંબાઈ નથી.")},
    {"parallel": ("समांतर", "સમાંતર"), "perpendicular": ("लंब", "લંબ"), "intersecting at the centre": ("केंद्र पर प्रतिच्छेदी", "કેન્દ્રમાં છેદતા"), "equal to the diameter": ("व्यास के बराबर", "વ્યાસ જેટલા")})
mcq("mcq09", ("एक चतुर्भुज ABCD एक वृत्त के परिगत है। यदि AB = 6 cm, BC = 7 cm और CD = 4 cm है, तो AD है:", "ચતુષ્કોણ ABCD એક વર્તુળની આસપાસ છે. જો AB = 6 cm, BC = 7 cm અને CD = 4 cm હોય, તો AD છે:"),
    ("$AB + CD = AD + BC$, अतः $10 = AD + 7$ और $AD = 3$ cm।", "$AB + CD = AD + BC$, તેથી $10 = AD + 7$ અને $AD = 3$ cm."),
    {"$3$ cm": ("सही!", "સાચું!"), "$5$ cm": ("$AD = AB + CD - BC = 3$ cm।", "$AD = AB + CD - BC = 3$ cm."), "$9$ cm": ("$AB + CD = AD + BC$ लीजिए।", "$AB + CD = AD + BC$ લો."), "$17$ cm": ("यह तीनों भुजाओं का योग है।", "આ ત્રણેય બાજુઓનો સરવાળો છે.")})
mcq("mcq10", ("किसी दी गई रेखा के समांतर वृत्त की अधिक से अधिक कितनी स्पर्श रेखाएँ हो सकती हैं?", "આપેલી રેખાને સમાંતર વર્તુળના વધુમાં વધુ કેટલા સ્પર્શકો હોઈ શકે?"), ("किसी दी गई दिशा के समांतर केवल एक व्यास के दोनों सिरों पर की स्पर्श रेखाएँ होती हैं।", "આપેલી દિશાને સમાંતર ફક્ત એક વ્યાસના બંને છેડા પરના સ્પર્શકો હોય છે."),
    {"$2$": ("सही!", "સાચું!"), "$1$": ("व्यास के हर सिरे पर एक है।", "વ્યાસના દરેક છેડે એક છે."), "$3$": ("केवल दो।", "ફક્ત બે."), "infinitely many": ("केवल दो स्पर्श रेखाएँ एक रेखा के समांतर हो सकती हैं।", "ફક્ત બે સ્પર્શકો એક રેખાને સમાંતર હોઈ શકે.")},
    {"infinitely many": ("अपरिमित रूप से अनेक", "અનંત")})
# Shine written
add("vsa1", ("केंद्र O वाले 8 cm त्रिज्या के वृत्त के केंद्र से 17 cm दूर स्थित बिंदु P से एक स्पर्श रेखा PT खींची गई है। PT ज्ञात कीजिए।", "કેન્દ્ર O વાળા 8 cm ત્રિજ્યાના વર્તુળના કેન્દ્રથી 17 cm દૂરના બિંદુ P માંથી સ્પર્શક PT દોર્યો છે. PT શોધો."),
    {0: ("$OT \\perp PT$ (त्रिज्या ⊥ स्पर्श रेखा), अतः $PT^{2} = 17^{2} - 8^{2} = 225$।", "$OT \\perp PT$ (ત્રિજ્યા ⊥ સ્પર્શક), તેથી $PT^{2} = 17^{2} - 8^{2} = 225$.")})
add("vsa2", ("P से केंद्र O वाले वृत्त पर PA और PB स्पर्श रेखाएँ हैं। यदि $\\angle APB = 50^\\circ$ है, तो $\\angle OAB$ ज्ञात कीजिए।", "P માંથી કેન્દ્ર O વાળા વર્તુળના સ્પર્શકો PA અને PB છે. જો $\\angle APB = 50^\\circ$ હોય, તો $\\angle OAB$ શોધો."),
    {0: ("$PA = PB$, अतः $\\angle PAB = \\angle PBA = \\dfrac{180^\\circ - 50^\\circ}{2} = 65^\\circ$।", "$PA = PB$, તેથી $\\angle PAB = \\angle PBA = \\dfrac{180^\\circ - 50^\\circ}{2} = 65^\\circ$.")})
add("sa1", ("बाह्य बिंदु P से केंद्र O वाले वृत्त पर दो स्पर्श रेखाएँ PA और PB खींची गई हैं। सिद्ध कीजिए कि $\\angle APB = 2\\angle OAB$।", "બાહ્ય બિંદુ P માંથી કેન્દ્ર O વાળા વર્તુળના બે સ્પર્શકો PA અને PB દોર્યા છે. સાબિત કરો કે $\\angle APB = 2\\angle OAB$."),
    {0: ("मान लीजिए $\\angle APB = \\theta$। $PA = PB$ (बाह्य बिंदु से स्पर्श रेखाएँ), अतः $\\angle PAB = \\angle PBA = 90^\\circ - \\dfrac{\\theta}{2}$।", "ધારો કે $\\angle APB = \\theta$. $PA = PB$ (બાહ્ય બિંદુમાંથી સ્પર્શકો), તેથી $\\angle PAB = \\angle PBA = 90^\\circ - \\dfrac{\\theta}{2}$."),
     1: ("$\\angle OAP = 90^\\circ$ (त्रिज्या ⊥ स्पर्श रेखा), अतः $\\angle OAB = 90^\\circ - \\angle PAB = \\dfrac{\\theta}{2}$।", "$\\angle OAP = 90^\\circ$ (ત્રિજ્યા ⊥ સ્પર્શક), તેથી $\\angle OAB = 90^\\circ - \\angle PAB = \\dfrac{\\theta}{2}$."),
     2: ("अतः $\\angle APB = 2\\angle OAB$।", "તેથી $\\angle APB = 2\\angle OAB$.")})
add("sa2", ("सिद्ध कीजिए कि वृत्त की किसी जीवा के सिरों पर खींची गई स्पर्श रेखाएँ जीवा के साथ बराबर कोण बनाती हैं।", "સાબિત કરો કે વર્તુળની જીવાના છેડા પર દોરેલા સ્પર્શકો જીવા સાથે સરખા ખૂણા બનાવે છે."),
    {0: ("मान लीजिए जीवा $AB$ के सिरों $A$ और $B$ पर स्पर्श रेखाएँ $P$ पर मिलती हैं।", "ધારો કે જીવા $AB$ ના છેડા $A$ અને $B$ પરના સ્પર્શકો $P$ માં મળે છે."),
     1: ("$PA = PB$ (बाह्य बिंदु से स्पर्श रेखाएँ)।", "$PA = PB$ (બાહ્ય બિંદુમાંથી સ્પર્શકો)."), 2: ("अतः $\\triangle PAB$ समद्विबाहु है और $\\angle PAB = \\angle PBA$।", "તેથી $\\triangle PAB$ સમદ્વિબાજુ છે અને $\\angle PAB = \\angle PBA$.")})
add("sa3", ("B पर समकोण वाले समकोण त्रिभुज ABC में एक वृत्त अंतर्निहित है। यदि BC = 7 cm और AB = 24 cm है, तो वृत्त की त्रिज्या ज्ञात कीजिए।", "B આગળ કાટખૂણાવાળા કાટકોણ ત્રિકોણ ABC માં એક વર્તુળ અંતર્ગત છે. જો BC = 7 cm અને AB = 24 cm હોય, તો વર્તુળની ત્રિજ્યા શોધો."),
    {1: ("$AB$ और $BC$ तक की त्रिज्याएँ शीर्ष $B$ के साथ भुजा $r$ का वर्ग बनाती हैं, अतः $B$ से स्पर्श रेखाएँ $r$ हैं; बराबर स्पर्श रेखाओं से $AC = (24 - r) + (7 - r)$।", "$AB$ અને $BC$ સુધીની ત્રિજ્યાઓ શિરોબિંદુ $B$ સાથે બાજુ $r$ નો ચોરસ બનાવે છે, તેથી $B$ માંથી સ્પર્શકો $r$ છે; સરખા સ્પર્શકોથી $AC = (24 - r) + (7 - r)$."),
     2: ("$25 = 31 - 2r$, अतः $r = 3$ cm।", "$25 = 31 - 2r$, તેથી $r = 3$ cm.")})
add("la1", ("सिद्ध कीजिए कि बाह्य बिंदु से वृत्त पर खींची गई स्पर्श रेखाओं की लंबाइयाँ बराबर होती हैं। अतः, यदि एक चतुर्भुज ABCD एक वृत्त के परिगत है, जिसमें AB = 8 cm, BC = 10 cm और CD = 12 cm है, तो AD ज्ञात कीजिए।",
             "સાબિત કરો કે બાહ્ય બિંદુમાંથી વર્તુળને દોરેલા સ્પર્શકોની લંબાઈ સરખી હોય છે. તે પરથી, જો ચતુષ્કોણ ABCD એક વર્તુળની આસપાસ હોય અને AB = 8 cm, BC = 10 cm અને CD = 12 cm હોય, તો AD શોધો."),
    {0: ("मान लीजिए $PQ$ और $PR$, $P$ से केंद्र $O$ वाले वृत्त पर स्पर्श रेखाएँ हैं; $OQ$, $OR$, $OP$ मिलाइए।", "ધારો કે $PQ$ અને $PR$ એ $P$ માંથી કેન્દ્ર $O$ વાળા વર્તુળના સ્પર્શકો છે; $OQ$, $OR$, $OP$ જોડો."),
     1: ("$OQ = OR$ (त्रिज्याएँ), $OP$ उभयनिष्ठ, $\\angle OQP = \\angle ORP = 90^\\circ$, अतः $\\triangle OQP \\cong \\triangle ORP$ (RHS) और $PQ = PR$।", "$OQ = OR$ (ત્રિજ્યાઓ), $OP$ સામાન્ય, $\\angle OQP = \\angle ORP = 90^\\circ$, તેથી $\\triangle OQP \\cong \\triangle ORP$ (કાકબા) અને $PQ = PR$."),
     2: ("$ABCD$ के लिए हर शीर्ष से बराबर स्पर्श रेखाओं से $AB + CD = AD + BC$।", "$ABCD$ માટે દરેક શિરોબિંદુમાંથી સરખા સ્પર્શકોથી $AB + CD = AD + BC$.")})
add("la2", ("3 cm त्रिज्या वाले वृत्त के परिगत एक त्रिभुज ABC है। स्पर्श बिंदु D, BC को BD = 6 cm और DC = 9 cm में विभाजित करता है। यदि त्रिभुज का क्षेत्रफल 54 cm² है, तो AB और AC ज्ञात कीजिए, और दर्शाइए कि त्रिभुज समकोण है।",
             "3 cm ત્રિજ્યાવાળા વર્તુળની આસપાસ ત્રિકોણ ABC છે. સ્પર્શબિંદુ D એ BC નું BD = 6 cm અને DC = 9 cm માં વિભાજન કરે છે. જો ત્રિકોણનું ક્ષેત્રફળ 54 cm² હોય, તો AB અને AC શોધો, અને બતાવો કે ત્રિકોણ કાટકોણ છે."),
    {0: ("बराबर स्पर्श रेखाएँ: मान लीजिए $AE = AF = x$; तब $AB = x + 6$, $AC = x + 9$, $BC = 15$।", "સરખા સ્પર્શકો: ધારો કે $AE = AF = x$; તો $AB = x + 6$, $AC = x + 9$, $BC = 15$."),
     1: ("क्षेत्रफल $= \\dfrac{1}{2} \\times 3 \\times (\\text{perimeter}) = 3(15 + x)$।", "ક્ષેત્રફળ $= \\dfrac{1}{2} \\times 3 \\times (\\text{perimeter}) = 3(15 + x)$."),
     2: ("$3(15 + x) = 54$, अतः $x = 3$।", "$3(15 + x) = 54$, તેથી $x = 3$."), 3: ("$AB = 9$ cm, $AC = 12$ cm", "$AB = 9$ cm, $AC = 12$ cm"),
     4: ("$9^{2} + 12^{2} = 81 + 144 = 225 = 15^{2}$, अतः $A$ पर कोण $90^\\circ$ है।", "$9^{2} + 12^{2} = 81 + 144 = 225 = 15^{2}$, તેથી $A$ આગળનો ખૂણો $90^\\circ$ છે.")})
add("cb1", ("एक वृत्ताकार बगीचे की त्रिज्या 5 m और केंद्र O है। O से 13 m दूर स्थित फाटक P से दो सीधे रास्ते PA और PB बगीचे की सीमा को A और B पर स्पर्श करते हैं।\n\n(i) रास्ते PA की लंबाई ज्ञात कीजिए। (1)\n\n(ii) बिना दोबारा गणना किए PB ज्ञात कीजिए। कारण दीजिए। (1)\n\n(iii) चतुर्भुज OAPB का क्षेत्रफल ज्ञात कीजिए। अथवा OAPB का परिमाप ज्ञात कीजिए। (2)",
             "એક વર્તુળાકાર બગીચાની ત્રિજ્યા 5 m અને કેન્દ્ર O છે. O થી 13 m દૂરના દરવાજા P માંથી બે સીધા રસ્તા PA અને PB બગીચાની કિનારીને A અને B માં સ્પર્શે છે.\n\n(i) રસ્તા PA ની લંબાઈ શોધો. (1)\n\n(ii) ફરી ગણતરી કર્યા વગર PB શોધો. કારણ આપો. (1)\n\n(iii) ચતુષ્કોણ OAPB નું ક્ષેત્રફળ શોધો. અથવા OAPB ની પરિમિતિ શોધો. (2)"),
    {0: ("(i) $OA \\perp PA$, अतः $PA = \\sqrt{13^{2} - 5^{2}} = 12$ m।", "(i) $OA \\perp PA$, તેથી $PA = \\sqrt{13^{2} - 5^{2}} = 12$ m."),
     1: ("(ii) $PB = 12$ m, क्योंकि बाह्य बिंदु से स्पर्श रेखाएँ बराबर होती हैं।", "(ii) $PB = 12$ m, કારણ કે બાહ્ય બિંદુમાંથી સ્પર્શકો સરખા હોય છે."),
     2: ("(iii) क्षेत्रफल $= 2 \\times \\dfrac{1}{2} \\times 5 \\times 12 = 60$ m²। अथवा परिमाप $= 5 + 12 + 12 + 5 = 34$ m।", "(iii) ક્ષેત્રફળ $= 2 \\times \\dfrac{1}{2} \\times 5 \\times 12 = 60$ m². અથવા પરિમિતિ $= 5 + 12 + 12 + 5 = 34$ m.")})
add("cb2", ("एक त्रिभुजाकार पार्क ABC में 4 m त्रिज्या का एक वृत्ताकार फव्वारा तीनों भुजाओं को स्पर्श करता है। फव्वारा BC को D पर, CA को E पर और AB को F पर स्पर्श करता है, जहाँ BD = 8 m और DC = 6 m है।\n\n(i) बराबर स्पर्श खंडों के युग्मों के नाम लिखिए। (1)\n\n(ii) यदि AF = x है, तो AB और AC को x के पदों में लिखिए। (1)\n\n(iii) क्षेत्रफल $= r \\times s$ ($s$ अर्धपरिमाप) और हीरोन सूत्र से x ज्ञात कीजिए। अथवा यदि x = 7 है, तो पार्क का परिमाप ज्ञात कीजिए। (2)",
             "એક ત્રિકોણાકાર બગીચા ABC માં 4 m ત્રિજ્યાનો વર્તુળાકાર ફુવારો ત્રણેય બાજુઓને સ્પર્શે છે. ફુવારો BC ને D માં, CA ને E માં અને AB ને F માં સ્પર્શે છે, જ્યાં BD = 8 m અને DC = 6 m છે.\n\n(i) સરખા સ્પર્શખંડોની જોડનાં નામ લખો. (1)\n\n(ii) જો AF = x હોય, તો AB અને AC ને x ના પદમાં લખો. (1)\n\n(iii) ક્ષેત્રફળ $= r \\times s$ ($s$ અર્ધપરિમિતિ) અને હેરોનના સૂત્રથી x શોધો. અથવા જો x = 7 હોય, તો બગીચાની પરિમિતિ શોધો. (2)"),
    {2: ("(iii) $4(14 + x) = \\sqrt{(14 + x) \\cdot x \\cdot 6 \\cdot 8}$ से $x = 7$। अथवा परिमाप $= 15 + 13 + 14 = 42$ m।", "(iii) $4(14 + x) = \\sqrt{(14 + x) \\cdot x \\cdot 6 \\cdot 8}$ પરથી $x = 7$. અથવા પરિમિતિ $= 15 + 13 + 14 = 42$ m.")})
fig("cb2", "△ABC का अंतःवृत्त", "△ABC નું અંતર્વર્તુળ")

AR = {
 "ch10.q.ar1": ("3 cm त्रिज्या वाले वृत्त के केंद्र से 5 cm दूर स्थित बिंदु से स्पर्श रेखा की लंबाई 4 cm है।", "वृत्त के किसी बिंदु पर स्पर्श रेखा, स्पर्श बिंदु से जाने वाली त्रिज्या पर लंब होती है।",
                "3 cm ત્રિજ્યાવાળા વર્તુળના કેન્દ્રથી 5 cm દૂરના બિંદુમાંથી સ્પર્શકની લંબાઈ 4 cm છે.", "વર્તુળના કોઈ પણ બિંદુએ સ્પર્શક, સ્પર્શબિંદુમાંથી પસાર થતી ત્રિજ્યાને લંબ હોય છે.",
                "$\\sqrt{5^{2} - 3^{2}} = 4$ cm।", "समकोण ही पाइथागोरस लगाने देता है।", "$\\sqrt{5^{2} - 3^{2}} = 4$ cm.", "કાટખૂણો જ પાયથાગોરસ વાપરવા દે છે.",
                "R के समकोण से $\\sqrt{5^{2} - 3^{2}} = 4$ cm मिलता है।", "R ના કાટખૂણાથી $\\sqrt{5^{2} - 3^{2}} = 4$ cm મળે છે."),
 "ch10.q.ar2": ("वृत्त के अंदर के बिंदु से वृत्त पर कोई स्पर्श रेखा नहीं खींची जा सकती।", "वृत्त के अंदर के बिंदु से जाने वाली हर रेखा वृत्त को दो बिंदुओं पर मिलती है।",
                "વર્તુળની અંદરના બિંદુમાંથી વર્તુળનો એક પણ સ્પર્શક દોરી ન શકાય.", "વર્તુળની અંદરના બિંદુમાંથી પસાર થતી દરેક રેખા વર્તુળને બે બિંદુમાં મળે છે.",
                "अंदर के बिंदु से जाने वाली हर रेखा वृत्त को दो बार काटती है।", "ठीक इसी कारण उससे जाने वाली कोई रेखा स्पर्श रेखा नहीं हो सकती।",
                "અંદરના બિંદુમાંથી પસાર થતી દરેક રેખા વર્તુળને બે વાર છેદે છે.", "બરાબર આ જ કારણે તેમાંથી પસાર થતી કોઈ રેખા સ્પર્શક ન હોઈ શકે.",
                "ऐसी हर रेखा छेदक है, अतः कोई स्पर्श रेखा नहीं हो सकती: R, A की व्याख्या करता है।", "આવી દરેક રેખા છેદિકા છે, તેથી કોઈ સ્પર્શક ન હોઈ શકે: R એ A સમજાવે છે."),
 "ch10.q.ar3": ("बाह्य बिंदु से वृत्त पर खींची गई दोनों स्पर्श रेखाओं की लंबाइयाँ बराबर होती हैं।", "वृत्त की अपरिमित रूप से अनेक स्पर्श रेखाएँ होती हैं।",
                "બાહ્ય બિંદુમાંથી વર્તુળને દોરેલા બંને સ્પર્શકોની લંબાઈ સરખી હોય છે.", "વર્તુળના અનંત સ્પર્શકો હોય છે.",
                "सर्वांगसम समकोण त्रिभुजों से स्पर्श रेखाएँ बराबर मिलती हैं।", "यह सत्य है, पर यह नहीं समझाता कि दो स्पर्श रेखाएँ बराबर क्यों हैं।",
                "એકરૂપ કાટકોણ ત્રિકોણથી સ્પર્શકો સરખા મળે છે.", "તે સાચું છે, પણ તે નથી સમજાવતું કે બે સ્પર્શકો સરખા કેમ છે.",
                "दोनों सत्य हैं, पर A सर्वांगसम त्रिभुजों से निकलता है, R से नहीं।", "બંને સાચાં છે, પણ A એકરૂપ ત્રિકોણ પરથી મળે છે, R પરથી નહિ."),
 "ch10.q.ar4": ("यदि बिंदु P से दो स्पर्श रेखाओं के बीच का कोण $70^\\circ$ है, तो स्पर्श बिंदुओं तक की त्रिज्याओं के बीच का कोण $120^\\circ$ है।", "स्पर्श रेखाओं के बीच का कोण और त्रिज्याओं के बीच का कोण मिलकर $180^\\circ$ होते हैं।",
                "જો બિંદુ P માંથી બે સ્પર્શકો વચ્ચેનો ખૂણો $70^\\circ$ હોય, તો સ્પર્શબિંદુઓ સુધીની ત્રિજ્યાઓ વચ્ચેનો ખૂણો $120^\\circ$ છે.", "સ્પર્શકો વચ્ચેનો ખૂણો અને ત્રિજ્યાઓ વચ્ચેનો ખૂણો મળીને $180^\\circ$ થાય છે.",
                "कोण $180^\\circ - 70^\\circ = 110^\\circ$ है।", "दो समकोणों वाले चतुर्भुज में कोण इसी प्रकार जुड़ते हैं।",
                "ખૂણો $180^\\circ - 70^\\circ = 110^\\circ$ છે.", "બે કાટખૂણાવાળા ચતુષ્કોણમાં ખૂણા આ રીતે ઉમેરાય છે.",
                "A असत्य है: कोण $180^\\circ - 70^\\circ = 110^\\circ$ है। R सत्य है।", "A ખોટું છે: ખૂણો $180^\\circ - 70^\\circ = 110^\\circ$ છે. R સાચું છે."),
 "ch10.q.ar5": ("स्पर्श बिंदु से स्पर्श रेखा पर खींचा गया लंब केंद्र से होकर जाता है।", "एक वृत्त की अधिक से अधिक एक स्पर्श रेखा हो सकती है।",
                "સ્પર્શબિંદુમાંથી સ્પર્શકને દોરેલો લંબ કેન્દ્રમાંથી પસાર થાય છે.", "વર્તુળનો વધુમાં વધુ એક સ્પર્શક હોઈ શકે.",
                "किसी बिंदु पर केवल एक लंब खींचा जा सकता है, और त्रिज्या ऐसा एक लंब है।", "वृत्त की अपरिमित रूप से अनेक स्पर्श रेखाएँ होती हैं।",
                "કોઈ બિંદુએ ફક્ત એક લંબ દોરી શકાય, અને ત્રિજ્યા એવો એક લંબ છે.", "વર્તુળના અનંત સ્પર્શકો હોય છે.",
                "A सत्य है। R असत्य है: वृत्त की अपरिमित रूप से अनेक स्पर्श रेखाएँ होती हैं।", "A સાચું છે. R ખોટું છે: વર્તુળના અનંત સ્પર્શકો હોય છે."),
}
